 * The resolved catalog a view renders its human text from. It is resolved once
 * when the Palette opens, so a view formats an ID and never re-resolves the
 * locale while the user is inside the Palette.
 */
catalog: CatalogBundle;
close(): void;

export function renderPaletteTabs(
	activeView: PaletteViewId,
	theme: Theme,
	styles: SessionUiStyles,
	catalog: CatalogBundle = defaultCatalog(),
): string {
	return PALETTE_TABS.map(({ view, label: id }) => {
		const label = catalogText(catalog, id);
		return view === activeView
			? theme.bg("selectedBg", theme.bold(styles.apply("palette.tab.active", `[${label}]`)))
			: styles.apply("palette.tab.inactive", ` ${label} `);
	}).join("  ");
}

/** Abbreviate a count for a column that has no room for every digit. */
export function compactNumber(value: number | undefined, catalog: CatalogBundle = defaultCatalog()): string {
	if (value === undefined) return catalogText(catalog, CatalogMessageId.paletteValueUnknown);
	if (value >= 1_000_000) return `${Math.round(value / 100_000) / 10}M`;
	if (value >= 1_000) return `${Math.round(value / 100) / 10}K`;
	return String(value);
}

/** Total frame rows, matching the overlay's 90% cap and one-row outer margins. */
export function paletteHeightBudget(rows: number): number {
	const height = Number.isFinite(rows) && rows > 0 ? Math.floor(rows) : 24;
	return Math.max(1, Math.min(height - 2, Math.floor(height * 0.9)));
}

export interface PaletteViewport {
	/** Zero-based index of the first visible row. */
	start: number;
	/** Zero-based exclusive end of the visible rows. */
	end: number;
	/** Rows the viewport can show. */

constructor(options?: { jouzuKeybindings?: JouzuKeybindingsManager; catalog?: CatalogBundle }) {
	// The default carries code defaults without user overrides; the product
	// wiring passes a manager loaded from the active keybindings.json.
	this.jouzuKeybindings = options?.jouzuKeybindings ?? createJouzuKeybindingsManagerFromConfig();
	// A caller without a resolved catalog (a unit test, for example) renders
	// English rather than a second copy of the text.
	this.catalog = options?.catalog ?? defaultCatalog();

	async open(
		ctx: ExtensionContext,
		route: PaletteRoute,
		factory: PaletteComponentFactory,
		options: PaletteSurfaceOptions = {},
	): Promise<boolean> {
		if (ctx.mode !== "tui") return false;
		if (this.active) {
			this.active.component?.route(route);
			this.active.handle?.focus();
			await this.active.promise;
			return true;
		}

		const token = {};
		let component: PaletteComponent | undefined;
		let handle: OverlayHandle | undefined;
		const presentation = selectPalettePresentation(options);
		const customOptions =
			presentation === "floating"
				? {
						overlay: true,
						overlayOptions: DEFAULT_PALETTE_OVERLAY_OPTIONS,
						onHandle: (value: OverlayHandle) => {
							handle = value;
							if (this.active?.token === token) this.active.handle = value;
						},
					}
				: undefined;

		let hidingTui: TUI | undefined;
		const promise = ctx.ui.custom<void>((tui, theme, keybindings, done) => {
			if (presentation === "floating" && installOverlayImageHiding(tui)) {
				imageHidingActive.add(tui);
				hidingTui = tui;
			}
			component = factory(
				{
					tui,
					theme,
					keybindings,
					jouzuKeybindings: this.jouzuKeybindings,
					styles: createSessionUiStyles(theme),
					catalog: this.catalog,
					close: () => done(undefined),
				},
				route,
			);
			if (this.active?.token === token) this.active.component = component;
			return component;
		}, customOptions);
		this.active = { token, component, handle, promise };
		try {
			await promise;
			return true;
		} finally {
			if (this.active?.token === token) this.active = undefined;
			if (hidingTui) {
				imageHidingActive.delete(hidingTui);
				// Redraw so hidden images return even if no other render is pending.
				hidingTui.requestRender();
			}
		}
	}
}

if (!editorInstalled) {
	ctx.ui.setEditorComponent(
		(tui, theme, keybindings) =>
			new SessionPromptEditor(tui, theme, keybindings, stylesFor(ctx.ui.theme), {
				topLine: (width) => sessionLine?.render(width)[0],
				slashCommandLocalizer: (command, description) => localizeSlashCommand(command, description),
				...(options.onModelPicker ? { onModelPicker: options.onModelPicker } : {}),
				...(options.onModelCycle ? { onModelCycle: options.onModelCycle } : {}),
				...(options.onScopedModelsCommand ? { onScopedModelsCommand: options.onScopedModelsCommand } : {}),
				exitAlias: exitAliasAvailable,
				exitAliasDescription: () => text.slashCommands?.quit,
			}),
	);
	editorInstalled = true;
}

private async openModelPicker(query?: string): Promise<boolean> {
	if (!this.options.onModelPicker) return false;
	this.preserveIdenticalSetText = true;
	try {
		return await this.options.onModelPicker(query);
	} catch {
		return false;
	} finally {
		this.preserveIdenticalSetText = false;
	}

override setAutocompleteProvider(provider: AutocompleteProvider): void {
	const filteredProvider: AutocompleteProvider = {
		...(provider.triggerCharacters ? { triggerCharacters: provider.triggerCharacters } : {}),
		getSuggestions: async (lines, cursorLine, cursorCol, options) => {
			const suggestions = await provider.getSuggestions(lines, cursorLine, cursorCol, options);
			if (suggestions && !suggestions.prefix.startsWith("/")) return suggestions;
			const items = [...(suggestions?.items ?? [])]
				.filter((item) => item.value !== "scoped-models")
				.map((item) => {
					const localized = this.options.slashCommandLocalizer?.(item.value, item.description);
					if (localized === undefined || localized === item.description) return item;
					return { ...item, description: localized };
				});
			return this.withExitAlias(lines, cursorLine, cursorCol, suggestions, items);
		},
		applyCompletion: (lines, cursorLine, cursorCol, item, prefix) =>
			provider.applyCompletion(lines, cursorLine, cursorCol, item, prefix),
		...(provider.shouldTriggerFileCompletion
			? {
					shouldTriggerFileCompletion: (lines: string[], cursorLine: number, cursorCol: number) =>
						provider.shouldTriggerFileCompletion?.(lines, cursorLine, cursorCol) ?? false,
				}
			: {}),
	};
	super.setAutocompleteProvider(filteredProvider);

override handleInput(data: string): void {
	const piPriorityAction =
		this.keybindingsManager.matches(data, "app.clipboard.pasteImage") ||
		this.keybindingsManager.matches(data, "app.interrupt") ||
		this.keybindingsManager.matches(data, "app.exit") ||
		this.keybindingsManager.matches(data, "tui.editor.historyPrevious") ||
		this.keybindingsManager.matches(data, "tui.editor.historyNext");
	if (piPriorityAction) {
		super.handleInput(data);
		return;
	}
	if (this.options.onModelCycle) {
		const direction = this.keybindingsManager.matches(data, "app.model.cycleForward")
			? "forward"
			: this.keybindingsManager.matches(data, "app.model.cycleBackward")
				? "backward"
				: undefined;
		if (direction) {
			if (this.onExtensionShortcut?.(data)) return;
			void this.options
				.onModelCycle(direction)
				.catch(() => false)
				.then((handled) => {
					if (!handled) super.handleInput(data);
				});
			return;
		}
	}
	if (this.options.onModelPicker && this.keybindingsManager.matches(data, "app.model.select")) {
		if (this.onExtensionShortcut?.(data)) return;
		void this.openModelPicker().then((opened) => {
			if (!opened) super.handleInput(data);
		});
		return;
	}
	if (this.keybindingsManager.matches(data, "tui.input.submit")) {
		const editorText = this.getText();
		if (this.options.onScopedModelsCommand && editorText.trim() === "/scoped-models") {
			if (this.onExtensionShortcut?.(data)) return;
			this.setText("");
			void this.options
				.onScopedModelsCommand()
				.catch(() => false)
				.then((handled) => {
					if (handled) return;
					this.setText(editorText);
					super.handleInput(data);
				});
			return;
		}
		if (this.options.onModelPicker) {
			const match = /^\/model(?:\s+(.*))?$/.exec(editorText.trim());
			if (match) {
				if (this.onExtensionShortcut?.(data)) return;
				this.setText("");
				void this.openModelPicker(match[1]?.trim() || undefined).then((opened) => {
					if (opened) return;
					this.setText(editorText);
					super.handleInput(data);
				});
				return;
			}
		}
	}
	super.handleInput(data);

	async attach(session) {
		// Reject an aborted automatic choice before Pi mutates the selected model.
		if (selection.automaticSelectionSignal) {
			const runtime = session.modelRuntime;
			const checkAuth = runtime.checkAuth.bind(runtime);
			hooks.set(runtime, "checkAuth", async (provider, options) => {
				const signal = selection.automaticSelectionSignal?.();
				signal?.throwIfAborted();
				const result = await checkAuth(
					provider,
					signal
						? { ...options, signal: options?.signal ? AbortSignal.any([signal, options.signal]) : signal }
						: options,
				);
				signal?.throwIfAborted();
				return result;
			});
		}
		// Session-lifetime hooks must sit below the delegate's branch-owned hooks.
		const setModel = session.setModel.bind(session);
		hooks.set(session, "setModel", async (...args) => {
			// Exempt the automatic call's async context, never unrelated concurrent choices.
			if (!selection.enteringAutomaticSelection()) await selection.beforeSelection();
			return setModel(...args);
		});
		const cycleModel = session.cycleModel.bind(session);
		hooks.set(session, "cycleModel", async (...args) => {
			if (!selection.enteringAutomaticSelection()) await selection.beforeSelection();
			return cycleModel(...args);
		});
		try {
			await delegate?.attach?.(session);
		} catch (error) {
			hooks.close();
			throw error;
		}
	},
	async dispose() {
		try {
			await selection.beforeSelection();
		} finally {
			try {
				await delegate?.dispose?.();
			} finally {
				hooks.close();
			}
		}
	},
	async beforeBranchChange(previous) {
		await selection.beforeSelection();
		await delegate?.beforeBranchChange?.(previous);
	},
	async branchChanged(next) {
		await delegate?.branchChanged?.(next);
	},
	async runCommand(submission, run) {
		if (delegate?.runCommand) await delegate.runCommand(submission, run);
		else await run();
	},
	async submit(submission, dispatch) {
		if (delegate) await delegate.submit(submission, dispatch);
		else await dispatch();
	},
};

export interface RuntimeDiagnostics {
	report(): string;
	about(): string;
	summary(): string;
	warnings(): string[];
}

const versionLines = () => {
	const current = installed();
	return [
		catalogText(catalog, DIAGNOSTICS_MESSAGE_ID.running, { version: metadata.displayVersion }),
		catalogText(catalog, DIAGNOSTICS_MESSAGE_ID.pi, { version: metadata.piVersion }),
		catalogText(catalog, DIAGNOSTICS_MESSAGE_ID.started, { started }),
		catalogText(catalog, DIAGNOSTICS_MESSAGE_ID.installed, {
			version: current?.displayVersion ?? catalogText(catalog, DIAGNOSTICS_MESSAGE_ID.versionUnavailable),
		}),
		...(current && changed(current) ? [catalogText(catalog, DIAGNOSTICS_MESSAGE_ID.installedDiffers)] : []),
	];
};
return {
	about: () => versionLines().join("\n"),
